BULLES_LOAD({"ep":"sophie/12","part":"text","paras":[{"poem":false,"s":[{"fr":"C’était le 19 juillet, jour de la naissance de Sophie ; elle avait quatre ans.","en":"It was the 19th of July, Sophie's birthday; she was four.","pt":"Era o dia 19 de julho, dia de anos da Sophie; fazia quatro anos.","es":"Era el 19 de julio, el cumpleaños de Sophie; cumplía cuatro años."},{"fr":"Sa maman lui faisait toujours un joli présent ce jour-là, mais elle ne lui disait jamais d’avance ce qu’elle lui donnerait.","en":"Her mother always gave her a pretty present on that day, but she never told her beforehand what she would give her.","pt":"A mãe dava-lhe sempre um presente bonito nesse dia, mas nunca lhe dizia antes o que lhe ia dar.","es":"Su mamá siempre le hacía un regalo bonito ese día, pero nunca le decía de antemano qué le iba a dar."},{"fr":"Sophie s’était levée plus tôt que d’habitude ; elle se dépêchait de s’habiller pour aller chez sa maman recevoir son cadeau.","en":"Sophie had got up earlier than usual; she was hurrying to get dressed so she could go to her mother's room and receive her present.","pt":"A Sophie tinha-se levantado mais cedo do que de costume; apressava-se a vestir-se para ir aos aposentos da mãe receber o presente.","es":"Sophie se había levantado más temprano que de costumbre; se daba prisa en vestirse para ir al cuarto de su mamá a recibir su regalo."}]},{"poem":false,"s":[{"fr":"« Vite, vite, ma bonne, je vous en prie, disait-elle ; j’ai si envie de savoir ce que maman me donnera pour ma fête !","en":"\"Quick, quick, Nanny, please,\" she was saying; \"I so want to know what Mama is going to give me for my birthday!","pt":"— Depressa, depressa, ama, por favor — dizia ela —; tenho tanta vontade de saber o que a mamã me vai dar pelos meus anos!","es":"«¡Deprisa, deprisa, niñera, se lo ruego!», decía; «¡tengo tantas ganas de saber qué me va a regalar mamá por mi cumpleaños!"}]},{"poem":false,"s":[{"fr":"Mais donnez-moi le temps de vous peigner.","en":"But give me time to comb your hair.","pt":"Mas dê-me tempo para a pentear.","es":"Pero deme tiempo para peinarla."},{"fr":"Vous ne pouvez pas vous en aller tout ébouriffée comme vous êtes.","en":"You can't go off all tousled as you are.","pt":"Não pode ir assim toda despenteada.","es":"No puede irse toda despeinada como está."},{"fr":"Ce serait une jolie manière de commencer vos quatre ans !…","en":"That would be a fine way to start being four!…","pt":"Seria uma bela maneira de começar os quatro anos!…","es":"¡Bonita manera de empezar sus cuatro años!…"},{"fr":"Tenez-vous donc tranquille, vous bougez toujours.","en":"Do keep still; you're always moving.","pt":"Esteja lá quieta, está sempre a mexer-se.","es":"Estese quieta, que no para de moverse."}],"who":{"fr":"La bonne","en":"the maid","pt":"a criada","es":"La niñera"}},{"poem":false,"s":[{"fr":"Aïe, aïe, vous m’arrachez les cheveux, ma bonne.","en":"Ow, ow, you're pulling my hair out, Nanny.","pt":"Ai, ai, está a arrancar-me os cabelos, ama.","es":"¡Ay, ay, que me arranca el pelo, niñera!"}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Parce que vous tournez la tête de tous les côtés ; là,… encore ! comment puis-je deviner de quel côté il vous plaira de tourner la tête ? »","en":"Because you turn your head every which way; there… again! How can I guess which way you'll decide to turn your head?\"","pt":"Porque vira a cabeça para todos os lados; pronto… outra vez! Como hei de eu adivinhar para que lado lhe apetece virar a cabeça?","es":"Porque gira la cabeza para todos lados; ahí… ¡otra vez! ¿Cómo voy a adivinar hacia qué lado le va a dar por girar la cabeza?»."}],"who":{"fr":"La bonne","en":"the maid","pt":"a criada","es":"La niñera"}},{"poem":false,"s":[{"fr":"Enfin Sophie fut habillée, peignée, et elle put courir chez sa maman.","en":"At last Sophie was dressed and combed, and she could run to her mother.","pt":"Por fim, a Sophie ficou vestida e penteada, e pôde correr para junto da mãe.","es":"Por fin Sophie estuvo vestida y peinada, y pudo correr al cuarto de su mamá."}]},{"poem":false,"s":[{"fr":"« Te voilà de bien bonne heure, Sophie, dit la maman en souriant.","en":"\"Here you are very early, Sophie,\" said her mother, smiling.","pt":"— Chegas bem cedo, Sophie — disse a mãe, a sorrir.","es":"«Qué temprano vienes, Sophie», dijo su mamá sonriendo."},{"fr":"Je vois que tu n’as pas oublié tes quatre ans et le cadeau que je te dois.","en":"\"I see you haven't forgotten that you're four and that I owe you a present.","pt":"— Vejo que não te esqueceste dos teus quatro anos nem do presente que te devo.","es":"«Ya veo que no te has olvidado de tus cuatro años ni del regalo que te debo."},{"fr":"Tiens, voici un livre, tu y trouveras de quoi t’amuser. »","en":"Here, this is a book; you'll find something in it to amuse you.\"","pt":"Toma, aqui tens um livro; vais encontrar nele com que te divertir.","es":"Toma, aquí tienes un libro; encontrarás en él con qué divertirte»."}]},{"poem":false,"s":[{"fr":"Sophie remercia sa maman d’un air embarrassé, et prit le livre, qui était en maroquin rouge.","en":"Sophie thanked her mother awkwardly and took the book, which was bound in red leather.","pt":"A Sophie agradeceu à mãe com ar embaraçado e pegou no livro, que era encadernado em marroquim vermelho.","es":"Sophie le dio las gracias a su mamá con aire apurado y cogió el libro, que era de tafilete rojo."}]},{"poem":false,"s":[{"fr":"« Que ferai-je de ce livre ? pensa-t-elle.","en":"\"What will I do with this book?\" she thought.","pt":"— Que hei de fazer a este livro? — pensou ela.","es":"«¿Qué voy a hacer con este libro?», pensó."},{"fr":"Je ne sais pas lire ; à quoi me servira-t-il ? »","en":"\"I can't read; what use will it be to me?\"","pt":"— Não sei ler; para que me serve?","es":"«No sé leer; ¿para qué me va a servir?»."}]},{"poem":false,"s":[{"fr":"La maman la regardait et riait.","en":"Her mother was watching her and laughing.","pt":"A mãe olhava para ela e ria-se.","es":"Su mamá la miraba y se reía."}]},{"poem":false,"s":[{"fr":"« Tu ne parais pas contente de mon présent, lui dit-elle ; c’est pourtant très joli ; il y a écrit dessus : les Arts.","en":"\"You don't seem pleased with my present,\" she said; \"and yet it's very pretty; it has 'The Arts' written on it.","pt":"— Não pareces contente com o meu presente — disse-lhe ela —; e no entanto é muito bonito; tem escrito em cima: As Artes.","es":"«No pareces contenta con mi regalo», le dijo; «y eso que es muy bonito; tiene escrito encima: Las Artes."},{"fr":"Je suis sûre qu’il t’amusera plus que tu ne le penses.","en":"I'm sure it will amuse you more than you think.","pt":"Tenho a certeza de que te vai divertir mais do que pensas.","es":"Estoy segura de que te divertirá más de lo que crees."}]},{"poem":false,"s":[{"fr":"Je ne sais pas, maman.","en":"I don't know, Mama.","pt":"Não sei, mamã.","es":"No sé, mamá."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Ouvre-le, tu verras. »","en":"Open it and you'll see.\"","pt":"Abre-o, vais ver.","es":"Ábrelo y verás»."}],"who":{"fr":"La maman","en":"Mother","pt":"a mãe","es":"Mamá"}},{"poem":false,"s":[{"fr":"Sophie voulut ouvrir le livre ; à sa grande surprise elle ne le put pas ; ce qui l’étonna plus encore, c’est qu’en le retournant il se faisait dans le livre un bruit étrange.","en":"Sophie tried to open the book; to her great surprise she couldn't; and what surprised her even more was that when she turned it over, something inside made a strange noise.","pt":"A Sophie quis abrir o livro; para sua grande surpresa, não conseguiu; e o que ainda a espantou mais foi que, ao virá-lo, se ouvia lá dentro um barulho estranho.","es":"Sophie quiso abrir el libro; para gran sorpresa suya, no pudo; y lo que más la extrañó fue que, al darle la vuelta, dentro del libro se oía un ruido raro."},{"fr":"Sophie regarda sa maman d’un air étonné.","en":"Sophie looked at her mother in astonishment.","pt":"A Sophie olhou para a mãe com ar espantado.","es":"Sophie miró a su mamá con asombro."},{"fr":"Mme de Réan rit plus fort et lui dit :","en":"Madame de Réan laughed harder and said:","pt":"A senhora de Réan riu-se ainda mais e disse-lhe:","es":"La señora de Réan se rio más fuerte y le dijo:"}]},{"poem":false,"s":[{"fr":"« C’est un livre extraordinaire ; il n’est pas comme tous les livres qui s’ouvrent tout seuls ;","en":"\"It's an extraordinary book; it isn't like ordinary books that open by themselves;","pt":"— É um livro extraordinário; não é como todos os livros, que se abrem sozinhos;","es":"«Es un libro extraordinario; no es como los demás libros, que se abren solos;"}]},{"poem":false,"s":[{"fr":"celui-ci ne s’ouvre que lorsqu’on appuie le pouce sur le milieu de la tranche. »","en":"this one only opens when you press your thumb on the middle of the edge.\"","pt":"este só se abre quando se carrega com o polegar no meio da lombada.","es":"este solo se abre cuando se aprieta con el pulgar en el centro del canto»."}]},{"poem":false,"s":[{"fr":"La maman appuya un peu le pouce ; le dessus s’ouvrit, et Sophie vit avec bonheur que ce n’était pas un livre, mais une charmante boîte à couleurs, avec des pinceaux, des godets et douze petits cahiers, pleins de charmantes images à peindre.","en":"Her mother pressed a little with her thumb; the lid opened, and Sophie saw with joy that it wasn't a book at all but a charming paint box, with brushes, little paint pots and twelve little books full of lovely pictures to colour.","pt":"A mãe carregou um pouco com o polegar; a tampa abriu-se, e a Sophie viu com alegria que não era um livro, mas uma linda caixa de tintas, com pincéis, godés e doze caderninhos cheios de lindas imagens para pintar.","es":"La mamá apretó un poco con el pulgar; la tapa se abrió, y Sophie vio con alegría que no era un libro, sino una preciosa caja de pinturas, con pinceles, cubiletes y doce cuadernillos llenos de dibujos preciosos para pintar."}]},{"poem":false,"s":[{"fr":"« Oh ! merci, ma chère maman, s’écria Sophie.","en":"\"Oh, thank you, dear Mama!\" cried Sophie.","pt":"— Oh, obrigada, minha querida mamã! — exclamou a Sophie.","es":"«¡Oh, gracias, mi querida mamá!», exclamó Sophie."},{"fr":"Que je suis contente !","en":"\"I'm so happy!","pt":"— Que contente estou!","es":"«¡Qué contenta estoy!"},{"fr":"Comme c’est joli !","en":"How pretty it is!","pt":"Que bonito!","es":"¡Qué bonito es!"}]},{"poem":false,"s":[{"fr":"Tu étais un peu attrapée tout à l’heure, quand tu as cru que je te donnais un vrai livre ; mais je ne t’aurais pas joué un si mauvais tour.","en":"You were a little taken in just now, when you thought I was giving you a real book; but I wouldn't have played such a mean trick on you.","pt":"Há bocado ficaste um bocadinho enganada, quando julgaste que te estava a dar um livro a sério; mas eu não te pregava uma partida tão má.","es":"Hace un momento estabas un poco chasqueada, cuando creíste que te regalaba un libro de verdad; pero no te habría gastado una broma tan pesada."},{"fr":"Tu pourras t’amuser à peindre dans la journée avec ton cousin Paul et tes amies Camille et Madeleine, que j’ai engagées à venir passer la journée avec toi : elles viendront à deux heures.","en":"You can have fun painting during the day with your cousin Paul and your friends Camille and Madeleine, whom I've invited to spend the day with you: they'll come at two o'clock.","pt":"Podes divertir-te a pintar durante o dia com o teu primo Paul e as tuas amigas Camille e Madeleine, que convidei para virem passar o dia contigo: chegam às duas horas.","es":"Podrás divertirte pintando durante el día con tu primo Paul y tus amigas Camille y Madeleine, a las que he invitado a pasar el día contigo: vendrán a las dos."},{"fr":"Ta tante d’Aubert m’a chargée de te donner de sa part ce petit thé ; elle ne pourra venir qu’à trois heures, et elle a voulu te faire son cadeau dès le matin. »","en":"Your Aunt d'Aubert asked me to give you this little tea set from her; she can't come until three o'clock, and she wanted you to have her present first thing in the morning.\"","pt":"A tua tia d'Aubert pediu-me que te desse da parte dela este servicinho de chá; ela só pode vir às três horas, e quis dar-te o presente logo de manhã.","es":"Tu tía d'Aubert me ha encargado que te dé de su parte este juego de té; ella no podrá venir hasta las tres, y ha querido darte su regalo desde por la mañana»."}],"who":{"fr":"La maman","en":"Mother","pt":"a mãe","es":"Mamá"}},{"poem":false,"s":[{"fr":"L’heureuse Sophie prit le plateau avec les six tasses, la théière, le sucrier et le pot à crème en argent.","en":"Happy Sophie took the tray with the six cups, the teapot, the sugar bowl and the silver cream jug.","pt":"A feliz Sophie pegou no tabuleiro com as seis chávenas, o bule, o açucareiro e a leiteira de prata.","es":"La feliz Sophie cogió la bandeja con las seis tazas, la tetera, el azucarero y la jarrita de nata de plata."},{"fr":"Elle demanda la permission de faire un vrai thé pour ses amies.","en":"She asked permission to make real tea for her friends.","pt":"Pediu licença para fazer um chá a sério para as amigas.","es":"Pidió permiso para hacer un té de verdad para sus amigas."}]},{"poem":false,"s":[{"fr":"« Non, lui dit Mme de Réan, vous répandriez la crème partout, vous vous brûleriez avec le thé.","en":"\"No,\" said Madame de Réan; \"you would spill the cream everywhere, and you'd burn yourselves with the tea.","pt":"— Não — disse-lhe a senhora de Réan —, entornavam a nata por todo o lado e queimavam-se com o chá.","es":"«No», le dijo la señora de Réan, «derramaríais la nata por todas partes y os quemaríais con el té."},{"fr":"Faites semblant d’en prendre, ce sera tout aussi amusant. »","en":"Pretend to drink some; it will be just as much fun.\"","pt":"Façam de conta que bebem; vai ser igualmente divertido.","es":"Haced como que lo tomáis; será igual de divertido»."}]},{"poem":false,"s":[{"fr":"Sophie ne dit rien, mais elle n’était pas contente.","en":"Sophie said nothing, but she wasn't pleased.","pt":"A Sophie não disse nada, mas não estava contente.","es":"Sophie no dijo nada, pero no estaba contenta."}]},{"poem":false,"s":[{"fr":"« À quoi me sert un ménage, se dit-elle, si je ne puis rien mettre dedans ?","en":"\"What's the use of a tea set,\" she said to herself, \"if I can't put anything in it?","pt":"— De que me serve um serviço — dizia para si — se não posso pôr nada lá dentro?","es":"«¿Para qué quiero un juego de té», se dijo, «si no puedo meter nada dentro?"},{"fr":"Mes amies se moqueront de moi.","en":"My friends will laugh at me.","pt":"As minhas amigas vão troçar de mim.","es":"Mis amigas se burlarán de mí."},{"fr":"Il faut que je cherche quelque chose pour remplir tout cela.","en":"I must find something to fill it all with.","pt":"Tenho de arranjar alguma coisa para encher isto tudo.","es":"Tengo que buscar algo para llenar todo esto."},{"fr":"Je vais demander à ma bonne. »","en":"I'll ask my nanny.\"","pt":"Vou pedir à ama.","es":"Se lo voy a pedir a la niñera»."}]},{"poem":false,"s":[{"fr":"Sophie dit à sa maman qu’elle allait montrer tout cela à sa bonne ; elle emporta sa boîte et son thé et courut dans sa chambre.","en":"Sophie told her mother she was going to show it all to her nanny; she took her box and her tea set and ran to her room.","pt":"A Sophie disse à mãe que ia mostrar tudo à ama; levou a caixa e o serviço de chá e correu para o quarto.","es":"Sophie le dijo a su mamá que iba a enseñarle todo aquello a la niñera; se llevó la caja y el juego de té y corrió a su cuarto."}]},{"poem":false,"s":[{"fr":"Tenez, ma bonne, voyez les jolies choses que m’ont données maman et ma tante d’Aubert.","en":"Look, Nanny, see the pretty things Mama and my Aunt d'Aubert have given me.","pt":"Olhe, ama, veja as coisas bonitas que me deram a mamã e a tia d'Aubert.","es":"Mire, niñera, vea las cosas tan bonitas que me han regalado mamá y mi tía d'Aubert."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Le joli ménage ! vous vous amuserez bien avec.","en":"What a pretty tea set! You'll have a lot of fun with it.","pt":"Que serviço tão bonito! Vai divertir-se muito com ele.","es":"¡Qué juego tan bonito! Se divertirá mucho con él."},{"fr":"Mais je n’aime pas beaucoup ce livre ; à quoi vous servira un livre, puisque vous ne savez pas lire ?","en":"But I don't much like that book; what use is a book to you, since you can't read?","pt":"Mas não gosto muito daquele livro; para que lhe serve um livro, se não sabe ler?","es":"Pero ese libro no me gusta mucho; ¿para qué le va a servir un libro, si no sabe leer?"}],"who":{"fr":"La bonne","en":"the maid","pt":"a criada","es":"La niñera"}},{"poem":false,"s":[{"fr":"Bravo ! voilà ma bonne attrapée comme moi.","en":"Hooray! Nanny's been taken in just like me.","pt":"Boa! A ama foi enganada como eu.","es":"¡Bravo! La niñera ha picado como yo."},{"fr":"Ce n’est pas un livre, c’est une boîte à couleurs.","en":"It isn't a book, it's a paint box.","pt":"Não é um livro, é uma caixa de tintas.","es":"No es un libro, es una caja de pinturas."}],"who":{"fr":"Sophie, riant","en":"Sophie, laughing","pt":"Sophie, a rir","es":"Sophie, riendo"}},{"poem":false,"s":[{"fr":"Et Sophie ouvrit la boîte, que la bonne trouva charmante.","en":"And Sophie opened the box, which the nanny thought was charming.","pt":"E a Sophie abriu a caixa, que a ama achou encantadora.","es":"Y Sophie abrió la caja, que a la niñera le pareció preciosa."},{"fr":"Après avoir causé sur ce qu’on ferait dans la journée, Sophie dit qu’elle avait voulu donner du thé à ses amies, mais que sa maman ne l’avait pas permis.","en":"After talking about what they would do during the day, Sophie said she had wanted to serve tea to her friends, but her mother hadn't allowed it.","pt":"Depois de conversarem sobre o que se faria durante o dia, a Sophie disse que tinha querido dar chá às amigas, mas que a mãe não tinha deixado.","es":"Después de charlar sobre lo que harían durante el día, Sophie dijo que había querido darles té a sus amigas, pero que su mamá no la había dejado."}]},{"poem":false,"s":[{"fr":"« Que mettrais-je dans ma théière, dans mon sucrier et dans mon pot à crème ?","en":"\"What would I put in my teapot, my sugar bowl and my cream jug?","pt":"— Que ponho eu no meu bule, no meu açucareiro e na minha leiteira?","es":"«¿Qué voy a poner en mi tetera, en mi azucarero y en mi jarrita de nata?"},{"fr":"Ne pourriez-vous pas, ma chère petite bonne, m’aider un peu et me donner quelque chose que je puisse faire manger à mes amies ?","en":"Couldn't you, my dear little nanny, help me a bit and give me something I could offer my friends to eat?\"","pt":"Não podia, minha querida amazinha, ajudar-me um bocadinho e dar-me alguma coisa que eu pudesse dar a comer às minhas amigas?","es":"¿No podría usted, mi querida niñera, ayudarme un poco y darme algo que pueda dar de comer a mis amigas?"}]},{"poem":false,"s":[{"fr":"— Non, ma pauvre petite, répondit la bonne : c’est impossible.","en":"\"No, my poor little one,\" answered the nanny, \"it's impossible.","pt":"— Não, minha pobre pequenina — respondeu a ama —: é impossível.","es":"—No, mi pobre pequeña», respondió la niñera: «es imposible."},{"fr":"Souvenez-vous que votre maman m’a dit qu’elle me renverrait si je vous donnais quelque chose à manger quand elle l’avait défendu. »","en":"Remember that your mama told me she would dismiss me if I gave you something to eat when she had forbidden it.\"","pt":"Lembre-se de que a sua mamã me disse que me despedia se eu lhe desse alguma coisa a comer quando ela o tivesse proibido.","es":"Acuérdese de que su mamá me dijo que me despediría si le daba algo de comer cuando ella lo había prohibido»."}]},{"poem":false,"s":[{"fr":"Sophie soupira et resta pensive ; petit à petit son visage s’éclaircit, elle avait une idée ; nous allons voir si l’idée était bonne.","en":"Sophie sighed and sat thinking; little by little her face brightened; she had an idea; we'll see whether it was a good one.","pt":"A Sophie suspirou e ficou pensativa; pouco a pouco a cara iluminou-se-lhe, tinha uma ideia; vamos ver se a ideia era boa.","es":"Sophie suspiró y se quedó pensativa; poco a poco se le iluminó la cara: tenía una idea; vamos a ver si la idea era buena."},{"fr":"Sophie joua, puis déjeuna ; en revenant de la promenade avec sa maman, elle dit qu’elle allait tout préparer pour l’arrivée de ses amies.","en":"Sophie played, then had lunch; coming back from a walk with her mother, she said she was going to get everything ready for her friends' arrival.","pt":"A Sophie brincou, depois almoçou; ao voltar do passeio com a mãe, disse que ia preparar tudo para a chegada das amigas.","es":"Sophie jugó y luego comió; al volver del paseo con su mamá, dijo que iba a prepararlo todo para la llegada de sus amigas."},{"fr":"Elle mit la boîte à couleurs sur une petite table.","en":"She put the paint box on a little table.","pt":"Pôs a caixa de tintas numa mesinha.","es":"Puso la caja de pinturas en una mesita."},{"fr":"Sur une autre table elle arrangea les six tasses, et au milieu elle mit le sucrier, la théière et le pot à crème.","en":"On another table she arranged the six cups, and in the middle she put the sugar bowl, the teapot and the cream jug.","pt":"Noutra mesa arrumou as seis chávenas e, no meio, pôs o açucareiro, o bule e a leiteira.","es":"En otra mesa colocó las seis tazas, y en el centro puso el azucarero, la tetera y la jarrita de nata."}]},{"poem":false,"s":[{"fr":"« À présent, dit-elle, je vais faire du thé. »","en":"\"Now,\" she said, \"I'm going to make tea.\"","pt":"— Agora — disse ela — vou fazer chá.","es":"«Ahora», dijo, «voy a hacer el té»."}]},{"poem":false,"s":[{"fr":"Elle prit la théière, alla dans le jardin, cueillit quelques feuilles de trèfle, qu’elle mit dans la théière ;","en":"She took the teapot, went into the garden, picked a few clover leaves and put them in the teapot;","pt":"Pegou no bule, foi ao jardim, apanhou umas folhas de trevo, que pôs no bule;","es":"Cogió la tetera, fue al jardín, cortó unas hojas de trébol y las metió en la tetera;"},{"fr":"ensuite elle alla prendre de l’eau dans l’assiette où on en mettait pour le chien de sa maman, et elle versa cette eau dans la théière.","en":"then she went and took some water from the dish where water was put out for her mother's dog, and she poured it into the teapot.","pt":"depois foi buscar água ao prato onde punham água para o cão da mãe, e deitou essa água no bule.","es":"luego fue a coger agua del plato donde se la ponían al perro de su mamá, y la echó en la tetera."}]},{"poem":false,"s":[{"fr":"« Là ! voilà le thé, dit-elle d’un air enchanté ; à présent je vais faire la crème. »","en":"\"There! That's the tea,\" she said, delighted; \"now I'm going to make the cream.\"","pt":"— Pronto! Aqui está o chá — disse ela, encantada —; agora vou fazer a nata.","es":"«¡Ya está! Aquí está el té», dijo con aire encantado; «ahora voy a hacer la nata»."},{"fr":"Elle alla prendre un morceau de blanc qui servait pour nettoyer l’argenterie ;","en":"She went and got a piece of the whiting used for cleaning the silver;","pt":"Foi buscar um bocado do branco que servia para limpar as pratas;","es":"Fue a coger un trozo del blanco que se usaba para limpiar la plata;"},{"fr":"elle en racla un peu avec son petit couteau, le versa dans le pot à crème, qu’elle remplit de l’eau du chien, mêla bien avec une petite cuiller, et, quand l’eau fut bien blanche, elle replaça le pot sur la table.","en":"she scraped a little off with her little knife, put it in the cream jug, filled the jug with the dog's water, stirred it well with a little spoon, and when the water was nice and white, she put the jug back on the table.","pt":"raspou um pouco com o canivete, deitou-o na leiteira, que encheu com a água do cão, misturou bem com uma colherinha e, quando a água ficou bem branca, voltou a pôr a leiteira na mesa.","es":"raspó un poco con su cuchillito, lo echó en la jarrita de nata, la llenó con el agua del perro, lo mezcló bien con una cucharilla y, cuando el agua estuvo bien blanca, volvió a poner la jarrita en la mesa."},{"fr":"Il ne lui restait plus que le sucrier à remplir ; elle reprit la craie à argenterie, en cassa de petits morceaux avec son couteau, remplit le sucrier, qu’elle posa sur la table, et regarda le tout d’un air enchanté.","en":"All she had left to fill was the sugar bowl; she took the silver chalk again, broke off little pieces with her knife, filled the sugar bowl, put it on the table and looked at it all with delight.","pt":"Só lhe faltava encher o açucareiro; pegou outra vez no giz das pratas, partiu uns bocadinhos com o canivete, encheu o açucareiro, que pousou na mesa, e olhou para tudo aquilo com ar encantado.","es":"Ya solo le quedaba llenar el azucarero; cogió otra vez la tiza de la plata, rompió trocitos con el cuchillo, llenó el azucarero, lo puso en la mesa y lo miró todo con aire encantado."}]},{"poem":false,"s":[{"fr":"« Là ! dit-elle en se frottant les mains, voilà un superbe thé ; j’espère que j’ai de l’esprit !","en":"\"There!\" she said, rubbing her hands. \"That's a superb tea; I'm so clever!","pt":"— Pronto! — disse ela, esfregando as mãos. — Aqui está um chá magnífico; que esperta que eu sou!","es":"«¡Ya está!», dijo frotándose las manos, «aquí tenemos un té magnífico; ¡qué lista soy!"},{"fr":"Je parie que Paul ni aucune de mes amies n’auraient eu une si bonne invention… »","en":"I bet neither Paul nor any of my friends would have come up with such a good idea…\"","pt":"Aposto que nem o Paul nem nenhuma das minhas amigas tinham tido uma ideia tão boa…","es":"Apuesto a que ni Paul ni ninguna de mis amigas habrían tenido un invento tan bueno…»."}]},{"poem":false,"s":[{"fr":"Sophie attendit ses amies encore une demi-heure, mais elle ne s’ennuya pas ;","en":"Sophie waited for her friends for another half hour, but she didn't get bored;","pt":"A Sophie ainda esperou meia hora pelas amigas, mas não se aborreceu;","es":"Sophie esperó a sus amigas otra media hora, pero no se aburrió;"},{"fr":"elle était si contente de son thé, qu’elle ne voulait pas s’en éloigner ;","en":"she was so pleased with her tea that she didn't want to leave it;","pt":"estava tão contente com o seu chá que não se queria afastar dele;","es":"estaba tan contenta con su té que no quería apartarse de él;"},{"fr":"elle se promenait autour de la table, le regardant d’un air joyeux, se frottait les mains et répétait :","en":"she walked round and round the table, looking at it joyfully, rubbing her hands and repeating:","pt":"andava à volta da mesa, a olhar para ele com ar alegre, esfregava as mãos e repetia:","es":"se paseaba alrededor de la mesa mirándolo con alegría, se frotaba las manos y repetía:"}]},{"poem":false,"s":[{"fr":"« Dieu ! que j’ai de l’esprit ! que j’ai de l’esprit ! »","en":"\"Goodness, how clever I am! How clever I am!\"","pt":"— Meu Deus, que esperta que eu sou! Que esperta que eu sou!","es":"«¡Dios mío, qué lista soy! ¡Qué lista soy!»."},{"fr":"Enfin Paul et les amies arrivèrent.","en":"At last Paul and her friends arrived.","pt":"Finalmente chegaram o Paul e as amigas.","es":"Por fin llegaron Paul y las amigas."},{"fr":"Sophie courut au-devant d’eux, les embrassa tous et les emmena bien vite dans le petit salon pour leur montrer ses belles choses.","en":"Sophie ran to meet them, kissed them all and quickly took them into the little sitting room to show them her lovely things.","pt":"A Sophie correu ao encontro deles, beijou-os a todos e levou-os depressa para a salinha, para lhes mostrar as suas coisas bonitas.","es":"Sophie corrió a su encuentro, los besó a todos y se los llevó deprisa al saloncito para enseñarles sus cosas bonitas."},{"fr":"La boîte à couleurs les attrapa d’abord comme elle avait attrapé Sophie et sa bonne.","en":"The paint box fooled them at first, just as it had fooled Sophie and her nanny.","pt":"A caixa de tintas enganou-os primeiro, como tinha enganado a Sophie e a ama.","es":"La caja de pinturas los engañó primero a ellos como había engañado a Sophie y a su niñera."},{"fr":"Ils trouvèrent le thé charmant et voulaient tout de suite commencer le repas, mais Sophie leur demanda d’attendre jusqu’à trois heures.","en":"They thought the tea set was charming and wanted to start the meal at once, but Sophie asked them to wait until three o'clock.","pt":"Acharam o serviço de chá encantador e queriam começar logo o lanche, mas a Sophie pediu-lhes que esperassem até às três horas.","es":"El juego de té les pareció precioso y querían empezar enseguida la merienda, pero Sophie les pidió que esperaran hasta las tres."},{"fr":"Ils se mirent donc tous à peindre les images des petits livres : chacun avait le sien.","en":"So they all began painting the pictures in the little books: each of them had one.","pt":"Puseram-se então todos a pintar as imagens dos caderninhos: cada um tinha o seu.","es":"Así que se pusieron todos a pintar los dibujos de los cuadernillos: cada uno tenía el suyo."},{"fr":"Quand on se fut bien amusé avec la boîte à couleurs et qu’on eut tout rangé soigneusement :","en":"When they had had plenty of fun with the paint box and had put everything carefully away:","pt":"Quando já se tinham divertido bastante com a caixa de tintas e arrumado tudo com cuidado:","es":"Cuando se hubieron divertido mucho con la caja de pinturas y lo hubieron recogido todo con cuidado:"}]},{"poem":false,"s":[{"fr":"« À présent, s’écria Paul, prenons le thé. »","en":"\"Now,\" cried Paul, \"let's have tea.\"","pt":"— Agora — exclamou o Paul — vamos tomar chá.","es":"«¡Ahora», exclamó Paul, «vamos a tomar el té!»."}]},{"poem":false,"s":[{"fr":"— Oui, oui, prenons le thé, répondirent toutes les petites filles ensemble.","en":"\"Yes, yes, let's have tea,\" answered all the little girls together.","pt":"— Sim, sim, vamos tomar chá — responderam as meninas todas ao mesmo tempo.","es":"—¡Sí, sí, vamos a tomar el té! —respondieron todas las niñas a la vez."}]},{"poem":false,"s":[{"fr":"Voyons, Sophie, fais les honneurs.","en":"Come on, Sophie, you be the hostess.","pt":"Vá, Sophie, faz as honras da casa.","es":"Vamos, Sophie, haz los honores."}],"who":{"fr":"Camille","en":"Camille","pt":"Camille","es":"Camille"}},{"poem":false,"s":[{"fr":"Asseyez-vous tous autour de la table…","en":"Sit down all round the table…","pt":"Sentem-se todos à volta da mesa…","es":"Sentaos todos alrededor de la mesa…"},{"fr":"Là, c’est bien…","en":"There, that's right…","pt":"Isso, está bem…","es":"Así, muy bien…"},{"fr":"Donnez-moi vos tasses, que j’y mette du sucre…","en":"Give me your cups so I can put sugar in them…","pt":"Deem-me as vossas chávenas, para eu pôr açúcar…","es":"Dadme vuestras tazas, que os ponga azúcar…"},{"fr":"À présent le thé,… puis la crème…","en":"Now the tea… then the cream…","pt":"Agora o chá… depois a nata…","es":"Ahora el té… luego la nata…"},{"fr":"Buvez maintenant.","en":"Now drink.","pt":"Agora bebam.","es":"Bebed ya."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"C’est singulier, le sucre ne fond pas.","en":"That's odd, the sugar isn't melting.","pt":"É esquisito, o açúcar não derrete.","es":"Qué raro, el azúcar no se deshace."}],"who":{"fr":"Madeleine","en":"Madeleine","pt":"Madeleine","es":"Madeleine"}},{"poem":false,"s":[{"fr":"Mêle bien, il fondra.","en":"Stir it well, it will melt.","pt":"Mexe bem, que ele derrete.","es":"Remueve bien y se deshará."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Mais ton thé est froid.","en":"But your tea is cold.","pt":"Mas o teu chá está frio.","es":"Pero tu té está frío."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"C’est parce qu’il est fait depuis longtemps.","en":"That's because it was made a long time ago.","pt":"É porque já foi feito há muito tempo.","es":"Es porque está hecho desde hace mucho rato."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Ah ! quelle horreur ! qu’est-ce que c’est ? ce n’est pas du thé, cela !","en":"Ugh! How horrible! What is it? This isn't tea!","pt":"Ah, que horror! Que é isto? Isto não é chá!","es":"¡Ah, qué horror! ¿Qué es esto? ¡Esto no es té!"}],"who":{"fr":"Camille goûte le thé et le rejette avec dégoût","en":"Camille tastes the tea and spits it out in disgust","pt":"Camille prova o chá e deita-o fora com nojo","es":"Camille prueba el té y lo escupe con asco"}},{"poem":false,"s":[{"fr":"C’est détestable ! cela sent la craie.","en":"It's disgusting! It tastes of chalk.","pt":"É detestável! Sabe a giz.","es":"¡Está asqueroso! Sabe a tiza."}],"who":{"fr":"Madeleine, le rejetant de même","en":"Madeleine, spitting it out too","pt":"Madeleine, deitando-o fora também","es":"Madeleine, escupiéndolo también"}},{"poem":false,"s":[{"fr":"Que nous as-tu donné là, Sophie ?","en":"What have you given us, Sophie?","pt":"Que nos deste, Sophie?","es":"¿Qué nos has dado, Sophie?"},{"fr":"C’est détestable, dégoûtant.","en":"It's disgusting, revolting.","pt":"É detestável, nojento.","es":"Es asqueroso, repugnante."}],"who":{"fr":"Paul, crachant à son tour","en":"Paul, spitting in his turn","pt":"Paul, cuspindo por sua vez","es":"Paul, escupiendo a su vez"}},{"poem":false,"s":[{"fr":"Vous trouvez…","en":"You think so…","pt":"Acham…","es":"¿Eso os parece?…"}],"who":{"fr":"Sophie, embarrassée","en":"Sophie, embarrassed","pt":"Sophie, embaraçada","es":"Sophie, apurada"}},{"poem":false,"s":[{"fr":"Comment, si nous trouvons ?","en":"What do you mean, do we think so?","pt":"Como, se achamos?","es":"¿Cómo que si nos lo parece?"},{"fr":"Mais c’est affreux de nous jouer un tour pareil !","en":"It's awful to play a trick like that on us!","pt":"É horrível pregares-nos uma partida destas!","es":"¡Es horrible gastarnos una broma así!"},{"fr":"Tu mériterais que nous te fissions avaler ton détestable thé.","en":"It would serve you right if we made you swallow your disgusting tea.","pt":"Merecias que te obrigássemos a engolir o teu chá detestável.","es":"Te merecerías que te hiciéramos tragar tu asqueroso té."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Vous êtes tous si difficiles que rien ne vous semble bon !","en":"You're all so fussy that nothing seems good to you!","pt":"São todos tão esquisitos que nada vos parece bom!","es":"¡Sois todos tan exigentes que nada os parece bueno!"}],"who":{"fr":"Sophie, se fâchant","en":"Sophie, getting cross","pt":"Sophie, zangando-se","es":"Sophie, enfadándose"}},{"poem":false,"s":[{"fr":"Avoue, Sophie, que, sans être difficile, on peut trouver ton thé très mauvais.","en":"Admit it, Sophie, you don't have to be fussy to find your tea very bad.","pt":"Confessa, Sophie, que, sem ser esquisito, pode-se achar o teu chá muito mau.","es":"Reconoce, Sophie, que, sin ser exigente, uno puede encontrar tu té muy malo."}],"who":{"fr":"Camille, souriant","en":"Camille, smiling","pt":"Camille, a sorrir","es":"Camille, sonriendo"}},{"poem":false,"s":[{"fr":"Quant à moi, je n’ai jamais goûté à quelque chose d’aussi mauvais.","en":"As for me, I've never tasted anything so bad.","pt":"Por mim, nunca provei nada tão mau.","es":"Yo, desde luego, nunca he probado nada tan malo."}],"who":{"fr":"Madeleine","en":"Madeleine","pt":"Madeleine","es":"Madeleine"}},{"poem":false,"s":[{"fr":"Avale donc, avale : tu verras si nous sommes difficiles.","en":"Go on, swallow it, swallow it: you'll see if we're fussy.","pt":"Engole lá, engole: vais ver se somos esquisitos.","es":"Trágatelo, anda, trágatelo: así verás si somos exigentes."}],"who":{"fr":"Paul, présentant la théière à Sophie","en":"Paul, handing Sophie the teapot","pt":"Paul, oferecendo o bule a Sophie","es":"Paul, ofreciéndole la tetera a Sophie"}},{"poem":false,"s":[{"fr":"Laisse-moi, tu m’ennuies.","en":"Leave me alone, you're annoying me.","pt":"Deixa-me, estás a aborrecer-me.","es":"Déjame, que me molestas."}],"who":{"fr":"Sophie, se débattant","en":"Sophie, struggling","pt":"Sophie, debatendo-se","es":"Sophie, forcejeando"}},{"poem":false,"s":[{"fr":"Ah ! nous sommes difficiles !","en":"Oh! So we're fussy!","pt":"Ah! Somos esquisitos!","es":"¡Ah, que somos exigentes!"},{"fr":"Ah ! tu trouves ton thé bon !","en":"Oh! So you think your tea is good!","pt":"Ah! Achas que o teu chá é bom!","es":"¡Ah, que tu té te parece bueno!"},{"fr":"Bois-le donc ainsi que ta crème. »","en":"Then drink it, and your cream too.\"","pt":"Então bebe-o, e a tua nata também.","es":"Pues bébetelo, y también tu nata»."}],"who":{"fr":"Paul, continuant","en":"Paul, going on","pt":"Paul, continuando","es":"Paul, continuando"}},{"poem":false,"s":[{"fr":"Et Paul, saisissant Sophie, lui versa le thé dans la bouche ;","en":"And Paul, grabbing Sophie, poured the tea into her mouth;","pt":"E o Paul, agarrando a Sophie, despejou-lhe o chá na boca;","es":"Y Paul, agarrando a Sophie, le echó el té en la boca;"},{"fr":"il allait en faire autant de la prétendue crème, malgré les cris et la colère de Sophie, lorsque Camille et Madeleine, qui étaient très bonnes et qui avaient pitié d’elle, se précipitèrent sur Paul pour lui arracher le pot à la crème.","en":"he was going to do the same with the so-called cream, in spite of Sophie's screams and rage, when Camille and Madeleine, who were very kind and felt sorry for her, threw themselves on Paul to snatch the cream jug from him.","pt":"ia fazer o mesmo com a pretensa nata, apesar dos gritos e da fúria da Sophie, quando a Camille e a Madeleine, que eram muito boas e tinham pena dela, se atiraram ao Paul para lhe arrancar a leiteira.","es":"iba a hacer lo mismo con la supuesta nata, a pesar de los gritos y la rabia de Sophie, cuando Camille y Madeleine, que eran muy buenas y le tenían lástima, se lanzaron sobre Paul para quitarle la jarrita de nata."},{"fr":"Paul, qui était furieux, les repoussa ; Sophie en profita pour se dégager et pour tomber dessus à coups de poing.","en":"Paul, who was furious, pushed them away; Sophie took the chance to free herself and lay into him with her fists.","pt":"O Paul, furioso, empurrou-as; a Sophie aproveitou para se soltar e lhe cair em cima aos murros.","es":"Paul, que estaba furioso, las apartó de un empujón; Sophie aprovechó para soltarse y caerle encima a puñetazos."},{"fr":"Camille et Madeleine tâchèrent alors de retenir Sophie ; Paul hurlait, Sophie criait, Camille et Madeleine appelaient au secours, c’était un train à assourdir ; les mamans accoururent effrayées.","en":"Then Camille and Madeleine tried to hold Sophie back; Paul was howling, Sophie was screaming, Camille and Madeleine were calling for help; it was a deafening racket; the mamas came running in alarm.","pt":"A Camille e a Madeleine tentaram então segurar a Sophie; o Paul berrava, a Sophie gritava, a Camille e a Madeleine pediam socorro; era um barulho de ensurdecer; as mães acorreram assustadas.","es":"Entonces Camille y Madeleine intentaron sujetar a Sophie; Paul aullaba, Sophie gritaba, Camille y Madeleine pedían socorro; era un jaleo ensordecedor; las mamás acudieron corriendo asustadas."},{"fr":"À leur aspect les enfants se tinrent tous immobiles.","en":"When they appeared, the children all froze.","pt":"Ao vê-las, as crianças ficaram todas imóveis.","es":"Al verlas, los niños se quedaron todos inmóviles."}]},{"poem":false,"s":[{"fr":"« Que se passe-t-il donc ? » demanda Mme de Réan d’un air inquiet et sévère.","en":"\"What on earth is going on?\" asked Madame de Réan, looking worried and stern.","pt":"— Que se passa? — perguntou a senhora de Réan com ar inquieto e severo.","es":"«¿Qué pasa aquí?», preguntó la señora de Réan con aire inquieto y severo."}]},{"poem":false,"s":[{"fr":"Personne ne répondit.","en":"Nobody answered.","pt":"Ninguém respondeu.","es":"Nadie respondió."}]},{"poem":false,"s":[{"fr":"Camille, explique-nous le sujet de cette bataille.","en":"Camille, explain to us what this battle is about.","pt":"Camille, explica-nos o motivo desta batalha.","es":"Camille, explícanos el motivo de esta batalla."}],"who":{"fr":"Madame de fleurville","en":"Madame de Fleurville","pt":"a senhora de Fleurville","es":"La señora de Fleurville"}},{"poem":false,"s":[{"fr":"Maman, Madeleine et moi nous ne nous battions avec personne.","en":"Mama, Madeleine and I weren't fighting anybody.","pt":"Mamã, a Madeleine e eu não estávamos a lutar com ninguém.","es":"Mamá, Madeleine y yo no nos estábamos peleando con nadie."}],"who":{"fr":"Camille","en":"Camille","pt":"Camille","es":"Camille"}},{"poem":false,"s":[{"fr":"Comment ! vous ne vous battiez pas ?","en":"What! You weren't fighting?","pt":"Como? Não estavam a lutar?","es":"¡Cómo! ¿No os estabais peleando?"},{"fr":"Toi tu tenais le bras de Sophie, et Madeleine tenait Paul par la jambe.","en":"You were holding Sophie's arm, and Madeleine was holding Paul by the leg.","pt":"Tu seguravas o braço da Sophie, e a Madeleine segurava o Paul pela perna.","es":"Tú sujetabas a Sophie del brazo, y Madeleine tenía a Paul agarrado de la pierna."}],"who":{"fr":"Madame de fleurville","en":"Madame de Fleurville","pt":"a senhora de Fleurville","es":"La señora de Fleurville"}},{"poem":false,"s":[{"fr":"C’était pour les empêcher de… de… jouer trop fort.","en":"That was to stop them… to stop them… playing too rough.","pt":"Era para os impedir de… de… brincarem com muita força.","es":"Era para impedirles… impedirles… jugar demasiado fuerte."}],"who":{"fr":"Camille","en":"Camille","pt":"Camille","es":"Camille"}},{"poem":false,"s":[{"fr":"Jouer ! tu appelles cela jouer !","en":"Playing! You call that playing!","pt":"Brincar! Chamas a isto brincar!","es":"¡Jugar! ¡A eso le llamas jugar!"}],"who":{"fr":"Madame de fleurville, avec un demi-sourire","en":"Madame de Fleurville, half smiling","pt":"a senhora de Fleurville, com um meio sorriso","es":"La señora de Fleurville, con media sonrisa"}},{"poem":false,"s":[{"fr":"Je vois que c’est Sophie et Paul qui se seront disputés comme à l’ordinaire ; Camille et Madeleine auront voulu les empêcher de se battre.","en":"I can see that Sophie and Paul must have quarrelled as usual; Camille and Madeleine must have tried to stop them fighting.","pt":"Estou a ver que foram a Sophie e o Paul que discutiram, como de costume; a Camille e a Madeleine devem ter querido impedi-los de lutar.","es":"Ya veo que han sido Sophie y Paul los que se han peleado, como de costumbre; Camille y Madeleine habrán querido impedir que se pegaran."},{"fr":"J’ai deviné, n’est-ce pas, ma petite Camille ?","en":"I've guessed right, haven't I, my little Camille?","pt":"Adivinhei, não é, minha pequena Camille?","es":"Lo he adivinado, ¿verdad, mi pequeña Camille?"}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Oui, madame.","en":"Yes, madame.","pt":"Sim, minha senhora.","es":"Sí, señora."}],"who":{"fr":"Camille, bien bas et rougissant","en":"Camille, very quietly, blushing","pt":"Camille, muito baixinho e a corar","es":"Camille, muy bajito y sonrojándose"}},{"poem":false,"s":[{"fr":"N’êtes-vous pas honteux, monsieur Paul, de vous conduire ainsi ?","en":"Aren't you ashamed, Master Paul, of behaving like this?","pt":"Não tem vergonha, senhor Paul, de se portar assim?","es":"¿No le da vergüenza, señor Paul, portarse así?"},{"fr":"À propos de rien vous vous fâchez, vous êtes prêt à vous battre…","en":"You lose your temper over nothing; you're ready to fight…","pt":"Por tudo e por nada se zanga, está pronto a lutar…","es":"Se enfada usted por nada y enseguida está dispuesto a pegarse…"}],"who":{"fr":"Madame d’aubert","en":"Madame d’Aubert","pt":"a senhora d’Aubert","es":"La señora d’Aubert"}},{"poem":false,"s":[{"fr":"Ce n’est pas à propos de rien, maman ; Sophie a voulu nous faire boire un thé tellement détestable que nous avons eu mal au cœur en le goûtant, et, quand nous nous sommes plaints, elle nous a dit que nous étions trop difficiles. »","en":"It wasn't over nothing, Mama; Sophie tried to make us drink tea so disgusting that we felt sick when we tasted it, and when we complained, she told us we were too fussy.\"","pt":"Não foi por nada, mamã; a Sophie quis obrigar-nos a beber um chá tão detestável que ficámos agoniados ao prová-lo e, quando nos queixámos, disse-nos que éramos esquisitos demais.","es":"No ha sido por nada, mamá; Sophie ha querido hacernos beber un té tan asqueroso que nos han dado náuseas al probarlo, y, cuando nos hemos quejado, nos ha dicho que éramos demasiado exigentes»."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Mme de Réan prit le pot à la crème, le sentit, y goûta du bout de la langue, fit une grimace de dégoût et dit à Sophie :","en":"Madame de Réan took the cream jug, sniffed it, tasted it with the tip of her tongue, made a face of disgust and said to Sophie:","pt":"A senhora de Réan pegou na leiteira, cheirou-a, provou com a ponta da língua, fez uma careta de nojo e disse à Sophie:","es":"La señora de Réan cogió la jarrita de nata, la olió, la probó con la punta de la lengua, hizo una mueca de asco y le dijo a Sophie:"}]},{"poem":false,"s":[{"fr":"« Où avez-vous pris cette horreur de prétendue crème, mademoiselle ?","en":"\"Where did you get this horrible so-called cream, miss?","pt":"— Onde foi buscar esta pretensa nata horrorosa, menina?","es":"«¿De dónde ha sacado usted esa porquería de supuesta nata, señorita?"}]},{"poem":false,"s":[{"fr":"Je l’ai faite, maman.","en":"I made it, Mama.","pt":"Fui eu que a fiz, mamã.","es":"La he hecho yo, mamá."}],"who":{"fr":"Sophie, la tête baissée et très honteuse","en":"Sophie, head down, very ashamed","pt":"Sophie, de cabeça baixa e muito envergonhada","es":"Sophie, con la cabeza gacha y muy avergonzada"}},{"poem":false,"s":[{"fr":"Vous l’avez faite ! et avec quoi ?…","en":"You made it! And with what?…","pt":"Foi a menina que a fez! E com quê?…","es":"¡La ha hecho usted! ¿Y con qué?…"},{"fr":"Répondez.","en":"Answer me.","pt":"Responda.","es":"Responda."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Avec le blanc à argenterie et l’eau du chien.","en":"With the silver whiting and the dog's water.","pt":"Com o branco das pratas e a água do cão.","es":"Con el blanco de la plata y el agua del perro."}],"who":{"fr":"Sophie, de même","en":"Sophie, doing the same","pt":"Sophie, do mesmo modo","es":"Sophie, del mismo modo"}},{"poem":false,"s":[{"fr":"Et votre thé, qu’est-ce que c’était ?","en":"And your tea, what was it?","pt":"E o seu chá, o que era?","es":"¿Y su té, qué era?"}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Des feuilles de trèfle et de l’eau du chien.","en":"Clover leaves and the dog's water.","pt":"Folhas de trevo e água do cão.","es":"Hojas de trébol y agua del perro."}],"who":{"fr":"Sophie, de même","en":"Sophie, doing the same","pt":"Sophie, do mesmo modo","es":"Sophie, del mismo modo"}},{"poem":false,"s":[{"fr":"Voilà un joli régal pour vos amies !","en":"A fine treat for your friends!","pt":"Bonito regalo para as suas amigas!","es":"¡Bonito festín para sus amigas!"},{"fr":"De l’eau sale, de la craie !","en":"Dirty water and chalk!","pt":"Água suja e giz!","es":"¡Agua sucia y tiza!"},{"fr":"Vous commencez bien vos quatre ans, mademoiselle : en désobéissant quand je vous avais défendu de faire du thé, en voulant faire avaler à vos amies un soi-disant thé dégoûtant, et en vous battant avec votre cousin.","en":"You're starting your fourth year well, miss: by disobeying when I had forbidden you to make tea, by trying to make your friends swallow a disgusting so-called tea, and by fighting with your cousin.","pt":"Começa bem os seus quatro anos, menina: a desobedecer quando a tinha proibido de fazer chá, a querer fazer as suas amigas engolir um pretenso chá nojento e a lutar com o seu primo.","es":"Bien empieza usted sus cuatro años, señorita: desobedeciendo cuando le había prohibido hacer té, queriendo hacer tragar a sus amigas un supuesto té asqueroso, y pegándose con su primo."},{"fr":"Je reprends votre ménage, pour vous empêcher de recommencer, et je vous aurais envoyée dîner dans votre chambre, si je ne craignais de gâter le plaisir de vos petites amies, qui sont si bonnes qu’elles souffriraient de votre punition. »","en":"I'm taking back your tea set to stop you doing it again, and I would have sent you to have dinner in your room if I weren't afraid of spoiling the fun for your little friends, who are so kind that they would suffer from your punishment.\"","pt":"Fico com o seu serviço, para a impedir de repetir, e tê-la-ia mandado jantar para o quarto se não tivesse medo de estragar o divertimento das suas amiguinhas, que são tão boas que iam sofrer com o seu castigo.","es":"Le quito el juego de té, para que no vuelva a hacerlo, y la habría mandado a cenar a su cuarto si no temiera estropearles la fiesta a sus amiguitas, que son tan buenas que sufrirían con su castigo»."}],"who":{"fr":"Madame de réan, examinant le sucrier","en":"Madame de Réan, examining the sugar bowl","pt":"a senhora de Réan, examinando o açucareiro","es":"La señora de Réan, examinando el azucarero"}},{"poem":false,"s":[{"fr":"Les mamans s’en allèrent en riant malgré elles du ridicule régal inventé par Sophie.","en":"The mamas went off, laughing in spite of themselves at the ridiculous treat Sophie had invented.","pt":"As mães foram-se embora, a rir sem querer do ridículo regalo inventado pela Sophie.","es":"Las mamás se fueron riéndose sin poder evitarlo del ridículo festín inventado por Sophie."},{"fr":"Les enfants restèrent seuls ; Paul et Sophie, honteux de leur bataille, n’osaient pas se regarder.","en":"The children were left alone; Paul and Sophie, ashamed of their fight, didn't dare look at each other.","pt":"As crianças ficaram sozinhas; o Paul e a Sophie, envergonhados da sua batalha, não se atreviam a olhar um para o outro.","es":"Los niños se quedaron solos; Paul y Sophie, avergonzados de su pelea, no se atrevían a mirarse."},{"fr":"Camille et Madeleine les embrassèrent, les consolèrent et tâchèrent de les réconcilier.","en":"Camille and Madeleine kissed them, comforted them and tried to make them friends again.","pt":"A Camille e a Madeleine beijaram-nos, consolaram-nos e tentaram fazer as pazes entre eles.","es":"Camille y Madeleine los besaron, los consolaron e intentaron reconciliarlos."},{"fr":"Sophie embrassa Paul, leur demanda pardon à tous, et tout fut oublié.","en":"Sophie kissed Paul, asked them all to forgive her, and everything was forgotten.","pt":"A Sophie deu um beijo ao Paul, pediu desculpa a todos, e tudo ficou esquecido.","es":"Sophie besó a Paul, les pidió perdón a todos y todo quedó olvidado."},{"fr":"On courut au jardin, où on attrapa huit superbes papillons, que Paul mit dans une boîte qui avait un couvercle de verre.","en":"They ran into the garden, where they caught eight superb butterflies, which Paul put in a box with a glass lid.","pt":"Correram para o jardim, onde apanharam oito borboletas magníficas, que o Paul meteu numa caixa com tampa de vidro.","es":"Corrieron al jardín, donde cazaron ocho mariposas magníficas, que Paul metió en una caja con tapa de cristal."},{"fr":"Le reste de l’après-midi se passa à arranger la boîte, pour que les papillons fussent bien logés ; on leur mit de l’herbe, des fleurs, des gouttes d’eau sucrée, des fraises, des cerises.","en":"The rest of the afternoon was spent arranging the box so the butterflies would be comfortable; they gave them grass, flowers, drops of sugar water, strawberries and cherries.","pt":"O resto da tarde passou-se a arranjar a caixa, para que as borboletas ficassem bem instaladas; puseram-lhes erva, flores, gotas de água com açúcar, morangos, cerejas.","es":"El resto de la tarde lo pasaron arreglando la caja para que las mariposas estuvieran bien alojadas; les pusieron hierba, flores, gotas de agua con azúcar, fresas y cerezas."},{"fr":"Quand le soir vint, et que chacun put partir, Paul emporta la boîte aux papillons, à la prière de Sophie, de Camille et de Madeleine, qui voyaient qu’il en avait envie.","en":"When evening came and everyone could leave, Paul took the butterfly box home, at the request of Sophie, Camille and Madeleine, who could see that he wanted it.","pt":"Quando chegou a noite e cada um se pôde ir embora, o Paul levou a caixa das borboletas, a pedido da Sophie, da Camille e da Madeleine, que viam que ele tinha vontade de ficar com ela.","es":"Cuando llegó la noche y cada uno pudo irse, Paul se llevó la caja de las mariposas, a ruegos de Sophie, Camille y Madeleine, que veían que tenía ganas de quedársela."}]}]});
